def maxAdjacentDistance(nums: List[int]) -> int:
    max_distance = 0
    n = len(nums)
    for i in range(n):
        # Calculate the absolute difference between adjacent elements, including circular
        distance = abs(nums[i] - nums[(i + 1) % n])
        if distance > max_distance:
            max_distance = distance
    return max_distance

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        first = s[i]
        second = s[i + 1]
        if first != second:
            if counts[first] == int(first) and counts[second] == int(second):
                return first + second
    return ""

