def maxDifference(s: str) -> int:
    from collections import Counter
    frequencies = Counter(s)
    odd_freq = [freq for freq in frequencies.values() if freq % 2 != 0]
    even_freq = [freq for freq in frequencies.values() if freq % 2 == 0]
    if not odd_freq or not even_freq:
        return 0
    return max(odd_freq) - min(even_freq)

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            left_boundary_ok = (i == 0) or (s[i - 1] != substring[0])
            right_boundary_ok = (i + k == n) or (s[i + k] != substring[0])
            if left_boundary_ok and right_boundary_ok:
                return True
    return False

