from typing import List

def maxSum(nums: List[int]) -> int:
    unique_nums = set()
    total_sum = 0
    for num in nums:
        if num > 0:
            unique_nums.add(num)
    total_sum = sum(unique_nums)
    return total_sum if total_sum > 0 else max(nums)

