def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    dp = [{} for _ in range(n)]  # each dict will hold <difference: length>
    max_length = 0
    for i in range(n):
        for j in range(i):
            diff = abs(nums[i] - nums[j])
            if diff in dp[j]:
                new_length = dp[j][diff] + 1
                dp[i][diff] = max(dp[i].get(diff, 0), new_length)
                max_length = max(max_length, dp[i][diff])

            # Check for subsequence extensions with previous differences
            for prev_diff, length in dp[j].items():
                if prev_diff >= diff:
                    new_length = length + 1
                    dp[i][diff] = max(dp[i].get(diff, 0), new_length)
                    max_length = max(max_length, dp[i][diff])
    return max_length

def calculateScore(s: str) -> int:
    score = 0
    marked = [False] * len(s)
    mirror = lambda c: chr(ord('z') - (ord(c) - ord('a')))

    for i in range(len(s)):
        if marked[i]:
            continue
        for j in range(i - 1, -1, -1):
            if not marked[j] and s[j] == mirror(s[i]):
                marked[i] = True
                marked[j] = True
                score += i - j
                break
    return score

