def maximumCoins(coins: List[List[int]], k: int) -> int:
    # Create a map to store the total coins in each bag position
    coin_map = {}

    # Fill the map with coins for each range
    for l, r, c in coins:
        for i in range(l, r + 1):
            if i in coin_map:
                coin_map[i] += c
            else:
                coin_map[i] = c

    # Create a sorted list of unique bag positions
    positions = sorted(coin_map.keys())

    if not positions:
        return 0

    max_coins = 0
    current_coins = 0
    left_idx = 0
    for right_idx in range(len(positions)):
        current_coins += coin_map[positions[right_idx]]

        # Shrink the window from the left if the distance between the
        # leftmost and rightmost bag is too large for a k-sized window.
        while positions[right_idx] - positions[left_idx] >= k:
            current_coins -= coin_map[positions[left_idx]]
            left_idx += 1

        max_coins = max(max_coins, current_coins)

    return max_coins

