def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque

    # Build the graph with weights
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Binary search for the minimum possible maximum edge weight
    def canAchieve(maxWeight):
        # Create a modified graph with edges <= maxWeight
        new_graph = defaultdict(list)
        for u in range(n):
            count = 0
            for v, w in graph[u]:
                if w <= maxWeight and count < threshold:
                    new_graph[u].append(v)
                    count += 1

        # Check if node 0 can be reached from all other nodes
        reachable = set()
        queue = deque([0])
        while queue:
            node = queue.popleft()
            if node not in reachable:
                reachable.add(node)
                queue.extend(new_graph[node])

        return len(reachable) == n

    left, right = 1, 10**6
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if canAchieve(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize dp array for minimum cost calculation
    dp = [[0] * 3 for _ in range(n)]

    # Solve for each case where the first house is painted a specific color
    min_cost = float('inf')
    for first_color in range(3):
        # Base case: set the first house's cost based on the chosen color
        for j in range(3):
            if j == first_color:
                dp[0][j] = cost[0][j]
            else:
                dp[0][j] = float('inf')

        # Fill dp array for houses 1 to n-1
        for i in range(1, n):
            for j in range(3):
                dp[i][j] = cost[i][j] + min(
                    dp[i-1][(j + 1) % 3],
                    dp[i-1][(j + 2) % 3]
                )

        # Only consider costs for the last house that do not match the first house's color
        last_cost = min(dp[n-1][(first_color + 1) % 3], dp[n-1][(first_color + 2) % 3])
        min_cost = min(min_cost, last_cost)

    return min_cost

from typing import List

def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    free_times = []

    # Calculate initial free time blocks
    if startTime[0] > 0:
        free_times.append(startTime[0])  # Free time before the first meeting
    for i in range(1, n):
        free_time = startTime[i] - endTime[i - 1]
        if free_time > 0:
            free_times.append(free_time)
    if endTime[-1] < eventTime:
        free_times.append(eventTime - endTime[-1])  # Free time after the last meeting

    # If we can reschedule meetings, calculate the maximum free time
    if k > 0:
        # Calculate the maximum free time we can create by moving meetings
        total_meeting_time = sum(end - start for start, end in zip(startTime, endTime))
        available_time = eventTime - total_meeting_time
        # We can only create free time up to the total available time
        max_free_time = min(available_time, sum(free_times) + k)
        return max_free_time
    else:
        return sum(free_times)
